  const _wanted = new Set();
  const _walk = (x) => {
    if (typeof x === 'string') { if (_names.has(x)) _wanted.add(x); return; }
    if (Array.isArray(x)) { for (const y of x) _walk(y); return; }
    if (x && typeof x === 'object') { for (const k in x) _walk(x[k]); }
  };
