    for (const v of allVars) {
      if (!_wanted.has(v.name)) continue;
      if (!_cov.has(v.variableCollectionId)) _cov.set(v.variableCollectionId, new Set());
      _cov.get(v.variableCollectionId).add(v.name);
    }
